values
  ('22222222-0000-0000-0000-000000000001', 'Squid Craft Games', 'squid-craft-games', 'Torneo masivo de Minecraft inspirado en El Juego del Calamar: cientos de creadores hispanos compiten por un premio de 100.000 dólares.', 'https://img.youtube.com/vi/y7U98tRDc6E/hqdefault.jpg', '33333333-0000-0000-0000-000000000001', null, 'finalizada', 2022, 2022, 'aprobada', '2026-01-10 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000002', 'TortillaLand', 'tortillaland', 'Serie de rol en Minecraft organizada por AuronPlay: una isla, decenas de creadores y tramas que marcaron una época.', 'https://img.youtube.com/vi/owOoMaSlAIE/hqdefault.jpg', '33333333-0000-0000-0000-000000000001', null, 'finalizada', 2020, 2021, 'aprobada', '2025-03-10 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000003', 'TortillaLand 2', 'tortillaland-2', 'Secuela de TortillaLand: los cubitos vuelven a la isla con nuevas tramas, bandas y caos.', 'https://img.youtube.com/vi/Im6Xi0khL8Q/hqdefault.jpg', '33333333-0000-0000-0000-000000000001', null, 'finalizada', 2023, 2023, 'aprobada', '2025-09-05 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000004', 'Karmaland', 'karmaland', 'La mítica serie de supervivencia de Vegetta777 y Willyrex: casi una década de aventuras en el mismo mundo.', 'https://img.youtube.com/vi/_u3NH5yGZt0/hqdefault.jpg', '33333333-0000-0000-0000-000000000001', null, 'finalizada', 2014, 2023, 'aprobada', '2025-11-20 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000005', 'Minecraft Hardcore', 'minecraft-hardcore', 'Rubius juega Minecraft Hardcore: si muere, se acaba el vídeo.', 'https://img.youtube.com/vi/DL00hKZqeD4/hqdefault.jpg', '33333333-0000-0000-0000-000000000001', null, 'activa', 2025, null, 'aprobada', '2026-08-16 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000006', 'Apocalipsis Minecraft', 'apocalipsis-minecraft', 'Willyrex y Vegetta sobreviven a un apocalipsis zombi en su mundo compartido.', 'https://img.youtube.com/vi/ZbKFpvhEvhw/hqdefault.jpg', '33333333-0000-0000-0000-000000000001', null, 'finalizada', 2016, 2018, 'aprobada', '2026-02-06 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000007', 'Dirty Business', 'dirty-business', 'Nexxuz levanta un imperio empresarial en Minecraft con negocios de dudosa legalidad.', 'https://img.youtube.com/vi/Nqx6YtGjI5Y/hqdefault.jpg', '33333333-0000-0000-0000-000000000001', null, 'activa', 2025, null, 'aprobada', '2026-07-04 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000008', 'Hardcore Salvaje', 'hardcore-salvaje', 'Willyrex sobrevive al modo hardcore con mods: hambre, zombis y colorines.', 'https://img.youtube.com/vi/Cf-YCm-eDUw/hqdefault.jpg', '33333333-0000-0000-0000-000000000001', null, 'activa', 2024, null, 'aprobada', '2026-07-18 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000009', 'Marbella Vice', 'marbella-vice', 'El servidor de roleplay de GTA V creado por TheGrefg que reunió a los mayores creadores hispanos.', 'https://img.youtube.com/vi/AiBDG0PRk7s/hqdefault.jpg', '33333333-0000-0000-0000-000000000002', null, 'finalizada', 2021, 2021, 'aprobada', '2025-06-15 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000010', 'SpainRP', 'spainrp', 'Uno de los servidores de roleplay de GTA V más populares de España.', 'https://img.youtube.com/vi/gH4E8VUQotU/hqdefault.jpg', '33333333-0000-0000-0000-000000000002', null, 'activa', 2019, null, 'aprobada', '2025-04-02 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000011', 'Infames RP', 'infames-rp', 'Servidor de roleplay de GTA V con tramas criminales y personajes inolvidables.', 'https://img.youtube.com/vi/XJ1x_B_pb0c/hqdefault.jpg', '33333333-0000-0000-0000-000000000002', null, 'activa', 2022, null, 'aprobada', '2025-10-03 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000012', 'London Eye', 'london-eye', 'Servidor de roleplay de GTA V ambientado en Londres, creado por JuanSGuarnizo.', 'https://img.youtube.com/vi/QLEJrpzGCYc/hqdefault.jpg', '33333333-0000-0000-0000-000000000002', null, 'finalizada', 2022, 2023, 'aprobada', '2025-07-08 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000013', 'GTA V Online', 'gta-v-online', 'Vegetta777 y Willyrex exprimen GTA Online: negocios, yates y delincuencia por un día.', 'https://img.youtube.com/vi/h7HiD_WuXtA/hqdefault.jpg', '33333333-0000-0000-0000-000000000002', null, 'activa', 2015, null, 'aprobada', '2025-02-14 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000014', 'Toni Gambino', 'toni-gambino', 'El icónico personaje de AuronPlay en Marbella Vice: el kerule más famoso del roleplay.', 'https://img.youtube.com/vi/uiEvATpHMZo/hqdefault.jpg', '33333333-0000-0000-0000-000000000003', null, 'finalizada', 2021, 2023, 'aprobada', '2025-05-21 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000015', 'Gustabo y Horacio', 'gustabo-y-horacio', 'Los personajes de AuronPlay en SpainRP: humor y caos en el servidor.', 'https://img.youtube.com/vi/vi6-oF3tsPs/hqdefault.jpg', '33333333-0000-0000-0000-000000000003', null, 'activa', 2020, null, 'aprobada', '2026-04-18 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000016', 'Komanche en Marbella Vice', 'komanche-en-marbella-vice', 'Komanche llega a Marbella Vice dispuesto a montar la fiesta de su vida.', 'https://img.youtube.com/vi/eDfcFtJkICM/hqdefault.jpg', '33333333-0000-0000-0000-000000000003', null, 'finalizada', 2021, 2021, 'aprobada', '2026-08-10 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000017', 'Unai en Marbella Vice', 'unai-en-marbella-vice', 'Ibai Llanos interpreta a Unai en Marbella Vice junto a Amara (Morphains).', 'https://img.youtube.com/vi/L_4UwKhKnHs/hqdefault.jpg', '33333333-0000-0000-0000-000000000003', null, 'finalizada', 2021, 2021, 'aprobada', '2026-03-11 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000018', 'Five Nights at Freddy''s', 'five-nights-at-freddys', 'Rubius se enfrenta a los animatrónicos: noches de terror en la pizzería.', 'https://img.youtube.com/vi/-N1it1yoJf0/hqdefault.jpg', '33333333-0000-0000-0000-000000000004', null, 'activa', 2024, null, 'aprobada', '2025-08-12 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000019', 'Resident Evil 2 Remake', 'resident-evil-2-remake', 'Vegetta777 sobrevive a Raccoon City con las historias de Leon y Claire.', 'https://img.youtube.com/vi/7f-MEr-fefc/hqdefault.jpg', '33333333-0000-0000-0000-000000000004', null, 'finalizada', 2019, 2019, 'aprobada', '2025-01-25 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000020', 'Fears to Fathom', 'fears-to-fathom', 'AuronPlay juega la saga de terror episódica Fears to Fathom.', 'https://img.youtube.com/vi/h4F4J6wG57I/hqdefault.jpg', '33333333-0000-0000-0000-000000000004', null, 'activa', 2023, null, 'aprobada', '2025-12-15 18:00:00+00'),
