  ('22222222-0000-0000-0000-000000000022', 'Poppy Playtime', 'poppy-playtime', 'Ibai Llanos se adentra en la fábrica de juguetes de Poppy Playtime.', 'https://img.youtube.com/vi/11_w83LogEw/hqdefault.jpg', '33333333-0000-0000-0000-000000000004', null, 'activa', 2022, null, 'aprobada', '2026-05-09 18:00:00+00'),
  ('22222222-0000-0000-0000-000000000023', '31 Minutos', '31-minutos', 'El noticiero de títeres chileno más querido de internet, ahora en YouTube.', 'https://img.youtube.com/vi/sM-RwR_cZOc/hqdefault.jpg', '33333333-0000-0000-0000-000000000005', null, 'finalizada', 2003, 2005, 'aprobada', '2026-06-20 18:00:00+00'),
